.comparison-header p { margin:0 0 2px; color:#879088; font-size:10px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; }
.comparison-header h1 { margin:0; font:600 29px "Newsreader",serif; }
.instruction { justify-self:end; padding:7px 11px; border-radius:999px; color:var(--green); background:#e7eee8; font-size:11px; font-weight:600; }
.comparison-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:18px; max-width:1440px; margin:0 auto; padding:24px; }
.option-title { display:flex; align-items:center; gap:10px; margin-bottom:10px; padding:0 3px; }
.option-title>span { display:grid; place-items:center; width:28px; height:28px; border:1px solid #ccd4cc; border-radius:50%; color:var(--green); background:white; font-weight:700; }
.option-title strong,.option-title small { display:block; }
.option-title small { color:#89918b; font-size:10px; }
.mini-app { height:610px; overflow:hidden; display:flex; border:1px solid #dce1da; border-radius:13px; background:white; box-shadow:0 12px 32px rgba(42,57,47,.08); }
.mini-app aside { width:125px; flex:0 0 auto; padding:19px 10px; border-right:1px solid var(--line); background:#f1f2ec; }
.mini-brand { margin:0 6px 32px; color:var(--green); font:600 18px "Newsreader",serif; }
.nav { display:flex; align-items:center; gap:5px; margin:4px 0; padding:8px 7px; border-radius:6px; color:#647068; font-size:9px; }
.nav.active { color:var(--green); background:#dfe8e0; font-weight:600; }
.nav em { margin-left:auto; font-size:8px; font-style:normal; }
.content { min-width:0; flex:1; }
.top { height:50px; padding:16px; border-bottom:1px solid var(--line); color:#a0a6a1; font-size:9px; }
.pad { position:relative; padding:22px 14px; }
h2 { margin:0 0 14px; font:600 20px "Newsreader",serif; }
.card { position:relative; display:grid; grid-template-columns:70px 1fr auto; gap:10px; min-height:125px; padding:10px; border:1px solid var(--line); border-radius:9px; background:white; }
.thumb { display:grid; place-items:center; border-radius:6px; color:white; background:#547680; font-weight:700; }
.body { min-width:0; padding-top:3px; }
.body small { color:#859088; font-size:8px; }
.body h3 { margin:4px 0; font:600 13px/1.15 "Newsreader",serif; }
.body p { margin:0 0 8px; color:#828a84; font-size:8px; }
.body>span { padding:3px 6px; border-radius:999px; color:#647168; background:#edf2ed; font-size:7px; }
.icon-action,.menu-toggle { align-self:start; display:grid; place-items:center; width:28px; height:28px; border:1px solid #dfe4df; border-radius:7px; color:#727d75; background:white; cursor:pointer; }
.icon-action.marked { color:white; border-color:var(--green); background:var(--green); }
.text-action { padding:5px 8px; border:1px solid #aab7ad; border-radius:6px; color:var(--green); background:white; font-size:8px; font-weight:600; cursor:pointer; }
.text-action.marked { color:white; border-color:var(--green); background:var(--green); }
.menu-toggle { border:0; letter-spacing:1px; }
.menu { position:absolute; z-index:2; right:8px; top:41px; width:130px; display:grid; padding:6px; border:1px solid var(--line); border-radius:7px; background:white; box-shadow:0 8px 20px rgba(33,47,38,.16); }
.menu button { border:0; padding:7px; border-radius:4px; background:white; text-align:left; font-size:8px; cursor:pointer; }
.menu button:hover { background:#eef2ee; }
.confirmation { margin-top:12px; padding:8px 10px; border-radius:7px; color:var(--green); background:#e8efe9; font-size:9px; font-weight:600; }
.option.selected .mini-app { border-color:#75917f; box-shadow:0 0 0 2px rgba(74,111,87,.12),0 12px 32px rgba(42,57,47,.08); }

/work/prototypes/read-later-options.js.content:
document.querySelectorAll('.option').forEach(option => {
  const menuToggle = option.querySelector('.menu-toggle');
  const menu = option.querySelector('.menu');
  if (menuToggle) menuToggle.addEventListener('click', () => { menu.hidden = !menu.hidden; });
  option.addEventListener('click', event => {
    const mark = event.target.closest('.mark');
    if (!mark) return;
    mark.classList.add('marked');
    if (mark.classList.contains('text-action')) mark.textContent = '✓ In Read later';
    if (menu) menu.hidden = true;
    option.querySelector('.later-count').textContent = '1';
    option.querySelector('.confirmation').hidden = false;
    option.classList.add('selected');
  });
});

