/work/implementation/public/styles.css.content:
:root {
  --canvas: #f7f6f2;
  --surface: #ffffff;
  --sidebar: #20243a;
  --sidebar-soft: #2a3049;
  --ink: #242536;
  --muted: #75778a;
  --line: #e4e3ea;
  --accent: #5651a6;
  --accent-dark: #403b8d;
  --accent-soft: #ecebfd;
  --coral: #e6785e;
  --coral-soft: #fff0eb;
  --green: #28755b;
  --green-soft: #e8f4ef;
  --danger: #b34e4e;
  --danger-soft: #fff0f0;
  --shadow: 0 18px 55px rgba(30, 31, 48, .15);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html { min-width: 940px; background: var(--canvas); }
body { margin: 0; color: var(--ink); background: var(--canvas); font-size: 14px; }
button, input, textarea { color: inherit; font: inherit; }
button { cursor: pointer; }

.loading-screen { min-height: 100vh; display: grid; place-content: center; justify-items: center; gap: 16px; color: var(--muted); }
.loading-glyph { width: 48px; height: 48px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px; transform: rotate(8deg); }
.loading-glyph i { border-radius: 4px; background: var(--accent); animation: pulse 1s ease-in-out infinite alternate; }
.loading-glyph i:nth-child(2), .loading-glyph i:nth-child(3) { opacity: .45; animation-delay: .3s; }
@keyframes pulse { to { opacity: .35; transform: scale(.88); } }

.shell { min-height: 100vh; }
.sidebar { position: fixed; inset: 0 auto 0 0; z-index: 10; width: 268px; display: flex; flex-direction: column; padding: 30px 20px 20px; color: #f7f7fb; background: var(--sidebar); }
.wordmark { display: inline-flex; align-items: center; gap: 12px; margin: 0 9px 35px; color: white; font: 700 24px/1 Georgia, serif; letter-spacing: -.02em; text-decoration: none; }
.wordmark-icon { width: 29px; height: 29px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 3px; padding: 4px; border: 1px solid rgba(255,255,255,.45); border-radius: 7px; transform: rotate(6deg); }
.wordmark-icon i { border-radius: 2px; background: #a8a5ed; }
.wordmark-icon i:nth-child(2), .wordmark-icon i:nth-child(3) { background: var(--coral); }
.view-nav { display: grid; gap: 5px; }
.nav-button { width: 100%; min-height: 43px; display: grid; grid-template-columns: 24px 1fr auto; align-items: center; gap: 8px; padding: 0 11px; border: 0; border-radius: 9px; color: #bfc1d2; background: transparent; text-align: left; }
.nav-button:hover { color: white; background: rgba(255,255,255,.06); }
.nav-button.active { color: white; background: var(--sidebar-soft); box-shadow: inset 3px 0 var(--coral); }
.nav-icon { font-size: 18px; text-align: center; }
.nav-count { color: #979ab1; font-size: 11px; }
.nav-button.active .nav-count { color: #d9daea; }
.tag-section { min-height: 0; margin-top: 33px; overflow: auto; }
.sidebar-heading { display: flex; justify-content: space-between; padding: 0 11px 9px; color: #85899f; font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.tag-nav { display: grid; gap: 3px; }
.tag-button { width: 100%; min-height: 35px; display: grid; grid-template-columns: 10px 1fr auto; align-items: center; gap: 8px; padding: 0 11px; border: 0; border-radius: 8px; color: #bfc1d2; background: transparent; text-align: left; }
.tag-button:hover { color: white; background: rgba(255,255,255,.06); }
.tag-button.active { color: white; background: #373d5a; }
.tag-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--tag-color, #a8a5ed); }
.tag-button small { color: #888ca3; }
.sidebar-empty { margin: 2px 11px; color: #74788f; font-size: 12px; line-height: 1.5; }
.sidebar-footer { display: flex; align-items: center; gap: 10px; margin-top: auto; padding: 16px 8px 0; border-top: 1px solid rgba(255,255,255,.09); }
.profile-mark { display: grid; place-items: center; width: 35px; height: 35px; flex: 0 0 auto; border-radius: 11px; color: #272c42; background: #dcdcf3; font-size: 9px; font-weight: 900; }
.sidebar-footer strong, .sidebar-footer small { display: block; }
.sidebar-footer strong { font-size: 12px; }
.sidebar-footer small { margin-top: 2px; color: #8f92a7; font-size: 10px; }

