.app-header { position: sticky; top: 0; z-index: 8; height: 78px; display: flex; align-items: center; gap: 22px; padding: 0 42px; border-bottom: 1px solid var(--line); background: rgba(255,255,255,.94); backdrop-filter: blur(15px); }
