kbd { padding: 3px 7px; border: 1px solid #dddde5; border-radius: 5px; color: #9b9dab; background: white; font: 10px inherit; }
.primary-button, .secondary-button, .quiet-button { min-height: 41px; padding: 0 16px; border-radius: 9px; font-weight: 700; }
