.title-row { display: flex; align-items: end; justify-content: space-between; gap: 25px; }
.overline { margin: 0 0 6px; color: #9394a2; font-size: 10px; font-weight: 900; letter-spacing: .14em; text-transform: uppercase; }
h1, h2, h3 { font-family: Georgia, "Times New Roman", serif; }
h1 { margin: 0; font-size: 38px; letter-spacing: -.025em; }
.collection-total { margin-bottom: 5px; color: var(--muted); font-size: 12px; }
