.bookmark-card.located { border-color: #8d88c4; box-shadow: 0 0 0 4px rgba(86,81,166,.12), 0 8px 24px rgba(30,31,48,.08); }
.preview { position: relative; min-height: 132px; overflow: hidden; display: grid; place-items: center; border-radius: 10px; color: white; background: linear-gradient(145deg, #5651a6, #8984ce); }
.preview.has-image { background-position: center; background-size: cover; }
