  const colors = ['#f29b78', '#8aa8d6', '#85bfa5', '#c39ad9', '#d8b467', '#83b9bd'];
  let hash = 0;
  for (const character of tag) hash = ((hash << 5) - hash + character.charCodeAt(0)) | 0;
  return colors[Math.abs(hash) % colors.length];
}

